  println("[PASS] Test 1: Manual IR")
  return true
}

# ----------------------------------------------------------------
# Test 2: 타입 시스템 검증
# ----------------------------------------------------------------

fn test_types() {
  println("=== Test 2: Type System ===")

  i32_t = ir_type_i32()
  assert(i32_t["name"] == "i32",    "i32 name")
  assert(i32_t["size"] == 4,        "i32 size")

  ptr_t = ir_type_ptr(ir_type_i64())
  assert(ptr_t["kind"] == "ptr",    "ptr kind")
  assert(ptr_t["size"] == 8,        "ptr size")

  arr_t = ir_type_array(ir_type_i8(), 16)
  assert(arr_t["kind"] == "array",  "array kind")
  assert(arr_t["count"] == 16,      "array count")
