	// ELF 실행
	elfBytes := codegen.BuildELFWithEntry(cm.Code, off)
	tmp, _ := os.CreateTemp("", "fir_cg_*.elf")
	tmp.Write(elfBytes)
	tmp.Close()
	os.Chmod(tmp.Name(), 0755)
	defer os.Remove(tmp.Name())

	cmd := exec.Command(tmp.Name())
	err = cmd.Run()
	var exitCode int64
	if err != nil {
		if ee, ok2 := err.(*exec.ExitError); ok2 {
			exitCode = int64(ee.ExitCode())
		}
