package main

import (
	"fmt"
	"os"
	"os/exec"
	"fir/src/codegen"
	"fir/src/interp"
	"fir/src/ir"
)

var vp, vf int

func check(label string, mod *ir.Module, entry string, args []interp.RVal, expected int64) {
	// interp
	ir_r, err := interp.ExecModule(mod, entry, args)
	if err != nil { fmt.Printf("[FAIL] %s interp: %v\n", label, err); vf++; return }

	// codegen
	cm, err := codegen.CompileModule(mod)
	if err != nil { fmt.Printf("[FAIL] %s codegen: %v\n", label, err); vf++; return }
	off := cm.FuncOff[entry]
	elfBytes := codegen.BuildELFWithEntry(cm.Code, off)

	tmp, _ := os.CreateTemp("", "fir_qemu_*.elf")
	tmp.Write(elfBytes); tmp.Close()
	os.Chmod(tmp.Name(), 0755)
	defer os.Remove(tmp.Name())

	// qemu-x86_64 실행
	cmd := exec.Command("qemu-x86_64", tmp.Name())
	err = cmd.Run()
	nativeVal := int64(0)
	if err != nil {
		if ee, ok := err.(*exec.ExitError); ok { nativeVal = int64(ee.ExitCode()) }
	}

	interpVal := ir_r.AsInt()
	if interpVal == expected && nativeVal == expected {
		fmt.Printf("[PASS] %-30s interp=%d native=%d\n", label, interpVal, nativeVal)
		vp++
	} else {
		fmt.Printf("[FAIL] %-30s interp=%d native=%d (expected=%d)\n", label, interpVal, nativeVal, expected)
		vf++
	}
}

func main() {
	fmt.Println("fir — interp == native (qemu-x86_64)")
	fmt.Println("=====================================")

	// Test 1: 상수 반환
	{
		e := ir.NewBlock("entry"); e.Add(ir.NewRet(ir.ConstInt(7, ir.I64())))
		fn := ir.NewFunction("main", nil, ir.I64(), true); fn.AddBlock(e)
		mod := ir.NewModule("t1"); mod.AddFunction(fn)
		check("const return 7", mod, "main", nil, 7)
	}

	// Test 2: 덧셈
	{
		p := []ir.Param{{Name:"a",Type:ir.I64()},{Name:"b",Type:ir.I64()}}
		e := ir.NewBlock("entry")
		e.Add(ir.NewBinop("add","r0",ir.I64(),ir.Reg("a",ir.I64()),ir.Reg("b",ir.I64())))
		e.Add(ir.NewRet(ir.Reg("r0",ir.I64())))
		fn := ir.NewFunction("add_fn", p, ir.I64(), true); fn.AddBlock(e)

		// wrapper: main calls add_fn(3,4) → 7
		wp := []ir.Param{}
		we := ir.NewBlock("entry")
		we.Add(ir.NewCall("r", ir.I64(), ir.GlobalRef("add_fn", ir.I64()),
			[]*ir.Value{ir.ConstInt(3,ir.I64()), ir.ConstInt(4,ir.I64())}))
		we.Add(ir.NewRet(ir.Reg("r", ir.I64())))
		wfn := ir.NewFunction("main", wp, ir.I64(), true); wfn.AddBlock(we)

		mod := ir.NewModule("t2"); mod.AddFunction(fn); mod.AddFunction(wfn)
		check("add(3,4)=7 via call", mod, "main", nil, 7)
	}

	// Test 3: 조건 분기 (양수면 1, 아니면 0)
	{
		// is_pos(5) → 1, wrap as main
		p := []ir.Param{{Name:"x",Type:ir.I64()}}
		e := ir.NewBlock("entry")
		e.Add(ir.NewICmp("gt","c",ir.I64(),ir.Reg("x",ir.I64()),ir.ConstInt(0,ir.I64())))
		e.Add(ir.NewBrCond(ir.Reg("c",ir.Bool()),"yes","no"))
		yes := ir.NewBlock("yes"); yes.Add(ir.NewRet(ir.ConstInt(1,ir.I64())))
		no  := ir.NewBlock("no");  no.Add(ir.NewRet(ir.ConstInt(0,ir.I64())))
		fn := ir.NewFunction("is_pos", p, ir.I64(), true)
		fn.AddBlock(e); fn.AddBlock(yes); fn.AddBlock(no)

		we := ir.NewBlock("entry")
		we.Add(ir.NewCall("r",ir.I64(),ir.GlobalRef("is_pos",ir.I64()),
			[]*ir.Value{ir.ConstInt(5,ir.I64())}))
		we.Add(ir.NewRet(ir.Reg("r",ir.I64())))
		wfn := ir.NewFunction("main", nil, ir.I64(), true); wfn.AddBlock(we)

		mod := ir.NewModule("t3"); mod.AddFunction(fn); mod.AddFunction(wfn)
		check("is_pos(5)=1", mod, "main", nil, 1)
	}

	// Test 4: alloca/store/load
	{
		e := ir.NewBlock("entry")
		e.Add(ir.NewAlloca("ptr", ir.I64()))
		e.Add(ir.NewStore(ir.I64(), ir.ConstInt(9,ir.I64()), ir.Reg("ptr",ir.Ptr(ir.I64()))))
		e.Add(ir.NewLoad("v", ir.I64(), ir.Reg("ptr",ir.Ptr(ir.I64()))))
		e.Add(ir.NewRet(ir.Reg("v",ir.I64())))
		fn := ir.NewFunction("main", nil, ir.I64(), true); fn.AddBlock(e)
		mod := ir.NewModule("t4"); mod.AddFunction(fn)
		check("alloca/store/load=9", mod, "main", nil, 9)
	}

	// Test 5: while sum 1+2+3+4+5 = 15
	{
		pi := ir.Reg("pi", ir.Ptr(ir.I64()))
		ps := ir.Reg("ps", ir.Ptr(ir.I64()))

		en := ir.NewBlock("entry")
		en.Add(ir.NewAlloca("pi", ir.I64()))
		en.Add(ir.NewAlloca("ps", ir.I64()))
		en.Add(ir.NewStore(ir.I64(), ir.ConstInt(1,ir.I64()), pi))
		en.Add(ir.NewStore(ir.I64(), ir.ConstInt(0,ir.I64()), ps))
		en.Add(ir.NewBr("cond"))

		cond := ir.NewBlock("cond")
		cond.Add(ir.NewLoad("ic", ir.I64(), pi))
		cond.Add(ir.NewICmp("le","cm",ir.I64(),ir.Reg("ic",ir.I64()),ir.ConstInt(5,ir.I64())))
		cond.Add(ir.NewBrCond(ir.Reg("cm",ir.Bool()),"body","exit"))

		body := ir.NewBlock("body")
		body.Add(ir.NewLoad("sc",ir.I64(),ps))
		body.Add(ir.NewLoad("ib",ir.I64(),pi))
		body.Add(ir.NewBinop("add","sn",ir.I64(),ir.Reg("sc",ir.I64()),ir.Reg("ib",ir.I64())))
		body.Add(ir.NewStore(ir.I64(),ir.Reg("sn",ir.I64()),ps))
		body.Add(ir.NewBinop("add","in",ir.I64(),ir.Reg("ib",ir.I64()),ir.ConstInt(1,ir.I64())))
		body.Add(ir.NewStore(ir.I64(),ir.Reg("in",ir.I64()),pi))
		body.Add(ir.NewBr("cond"))

		exitB := ir.NewBlock("exit")
		exitB.Add(ir.NewLoad("sf",ir.I64(),ps))
		exitB.Add(ir.NewRet(ir.Reg("sf",ir.I64())))

		fn := ir.NewFunction("main", nil, ir.I64(), true)
		fn.AddBlock(en); fn.AddBlock(cond); fn.AddBlock(body); fn.AddBlock(exitB)
		mod := ir.NewModule("t5"); mod.AddFunction(fn)
		check("while sum(1..5)=15", mod, "main", nil, 15)
	}

	fmt.Println("=====================================")
	fmt.Printf("Results: %d/%d PASS\n", vp, vp+vf)
	if vf == 0 {
		fmt.Println()
		fmt.Println("✓ interp == native VERIFIED")
		fmt.Println("✓ fir Phase 1 COMPLETE")
	}
}
