// 모듈 컴파일러
// ----------------------------------------------------------------

type CompiledModule struct {
	Code     []byte            // 전체 코드 섹션
	FuncOff  map[string]int    // 함수명 → 코드 내 오프셋
	FuncSize map[string]int
