package main

import (
	"fmt"
	"os"
	"os/exec"
	"fir/src/codegen"
	"fir/src/ir"
)

func run(name string, mod *ir.Module, entry string, expected int) {
	cm, err := codegen.CompileModule(mod)
	if err != nil { fmt.Printf("[ERR] %s: %v\n", name, err); return }
	off := cm.FuncOff[entry]
	elf := codegen.BuildELFWithEntry(cm.Code, off)
	tmp, _ := os.CreateTemp("", "fir_dbg_*.elf")
	tmp.Write(elf); tmp.Close(); os.Chmod(tmp.Name(), 0755)
	defer os.Remove(tmp.Name())
	cmd := exec.Command("qemu-x86_64", tmp.Name())
	err = cmd.Run()
	exit := 0
	if err != nil { if ee, ok := err.(*exec.ExitError); ok { exit = ee.ExitCode() } }
	status := "PASS"
	if exit != expected { status = "FAIL" }
	fmt.Printf("[%s] %-35s got=%d expected=%d\n", status, name, exit, expected)
}

func main() {
	// Case A: main 직접 add (인라인)
	{
		e := ir.NewBlock("entry")
		e.Add(ir.NewBinop("add","r",ir.I64(),ir.ConstInt(3,ir.I64()),ir.ConstInt(4,ir.I64())))
		e.Add(ir.NewRet(ir.Reg("r",ir.I64())))
		fn := ir.NewFunction("main", nil, ir.I64(), true); fn.AddBlock(e)
		mod := ir.NewModule("a"); mod.AddFunction(fn)
		run("inline add 3+4=7", mod, "main", 7)
	}

	// Case B: add_fn(a,b) 단독 호출 — main이 없고 add_fn이 entry
	{
		p := []ir.Param{{Name:"a",Type:ir.I64()},{Name:"b",Type:ir.I64()}}
		e := ir.NewBlock("entry")
		e.Add(ir.NewBinop("add","r",ir.I64(),ir.Reg("a",ir.I64()),ir.Reg("b",ir.I64())))
		e.Add(ir.NewRet(ir.Reg("r",ir.I64())))
		fn := ir.NewFunction("add_fn", p, ir.I64(), true); fn.AddBlock(e)
		mod := ir.NewModule("b"); mod.AddFunction(fn)
		// _start가 add_fn 호출 — 인자 없이 → rdi/rsi = 쓰레기값
		// 이 케이스는 의미없음 (인자 전달 불가)
		_ = mod
	}

	// Case C: main → call add_fn(3,4)
	{
		p := []ir.Param{{Name:"a",Type:ir.I64()},{Name:"b",Type:ir.I64()}}
		e := ir.NewBlock("entry")
		e.Add(ir.NewBinop("add","r",ir.I64(),ir.Reg("a",ir.I64()),ir.Reg("b",ir.I64())))
		e.Add(ir.NewRet(ir.Reg("r",ir.I64())))
		addFn := ir.NewFunction("add_fn", p, ir.I64(), false); addFn.AddBlock(e)

		me := ir.NewBlock("entry")
		me.Add(ir.NewCall("res",ir.I64(),ir.GlobalRef("add_fn",ir.I64()),
			[]*ir.Value{ir.ConstInt(3,ir.I64()),ir.ConstInt(4,ir.I64())}))
		me.Add(ir.NewRet(ir.Reg("res",ir.I64())))
		mainFn := ir.NewFunction("main", nil, ir.I64(), true); mainFn.AddBlock(me)

		mod := ir.NewModule("c"); mod.AddFunction(addFn); mod.AddFunction(mainFn)
		run("main→call add_fn(3,4)=7", mod, "main", 7)
	}

	// Case D: param pass 검증 — fn(x) { return x }  x=5
	{
		p := []ir.Param{{Name:"x",Type:ir.I64()}}
		e := ir.NewBlock("entry")
		e.Add(ir.NewRet(ir.Reg("x",ir.I64())))
		idFn := ir.NewFunction("id", p, ir.I64(), false); idFn.AddBlock(e)

		me := ir.NewBlock("entry")
		me.Add(ir.NewCall("r",ir.I64(),ir.GlobalRef("id",ir.I64()),
			[]*ir.Value{ir.ConstInt(5,ir.I64())}))
		me.Add(ir.NewRet(ir.Reg("r",ir.I64())))
		mainFn := ir.NewFunction("main", nil, ir.I64(), true); mainFn.AddBlock(me)

		mod := ir.NewModule("d"); mod.AddFunction(idFn); mod.AddFunction(mainFn)
		run("main→call id(5)=5", mod, "main", 5)
	}
}
